// Naive string matching (good enough for small constraints)
bool is_substring(char *text, char *pattern) {
    int n = strlen(text);
    int m = strlen(pattern);
    if (m == 0) return true;
    if (m > n) return false;

    for (int i = 0; i <= n - m; i++) {
        int j;
        for (j = 0; j < m; j++) {
            if (text[i + j] != pattern[j])
                break;
        }
        if (j == m)
            return true;
    }
    return false;
}

