import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String T = br.readLine();
        int Q = Integer.parseInt(br.readLine());

        List<String> patterns = new ArrayList<>();
        for (int i = 0; i < Q; i++) {
            patterns.add(br.readLine());
        }

        // Build prefix function for T to use KMP for each pattern
        // Actually, we can use Java's built-in indexOf for simplicity, 
        // but for large constraints we implement KMP.

        for (String P : patterns) {
            if (kmpSearch(T, P)) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }
    }

    private static boolean kmpSearch(String text, String pattern) {
        if (pattern.isEmpty()) return true;
        int n = text.length();
        int m = pattern.length();
        if (m > n) return false;

        // Build prefix function for pattern
        int[] pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && pattern.charAt(i) != pattern.charAt(j)) {
                j = pi[j - 1];
            }
            if (pattern.charAt(i) == pattern.charAt(j)) {
                j++;
            }
            pi[i] = j;
        }

        // Search
        int j = 0;
        for (int i = 0; i < n; i++) {
            while (j > 0 && text.charAt(i) != pattern.charAt(j)) {
                j = pi[j - 1];
            }
            if (text.charAt(i) == pattern.charAt(j)) {
                j++;
            }
            if (j == m) {
                return true;
            }
        }
        return false;
    }
}

