import sys

def build_kmp_table(pattern):
    """Build the prefix function for KMP algorithm."""
    m = len(pattern)
    table = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and pattern[i] != pattern[j]:
            j = table[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
            table[i] = j
    return table

def kmp_search(text, pattern):
    """KMP search: returns True if pattern found in text."""
    if not pattern:
        return True
    n, m = len(text), len(pattern)
    if m > n:
        return False
    table = build_kmp_table(pattern)
    j = 0
    for i in range(n):
        while j > 0 and text[i] != pattern[j]:
            j = table[j - 1]
        if text[i] == pattern[j]:
            j += 1
            if j == m:
                return True
    return False

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    T = data[0].strip()
    q = int(data[1].strip())
    out_lines = []
    for i in range(2, 2 + q):
        P = data[i].strip()
        if kmp_search(T, P):
            out_lines.append("1")
        else:
            out_lines.append("0")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
